        ..writeAsStringSync('approvalMode: yolo\n');
      workspace = Directory.systemTemp.createTempSync('fa_ctrl_c_ws_');
    });

    tearDown(() {
      tempHome.deleteSync(recursive: true);
      workspace.deleteSync(recursive: true);
    });

