  void sendText(String text) => pty.write(text);

  /// Sends Enter (CR — dart_tui maps both CR and LF to 'enter').
  void sendEnter() => pty.write('\r');

  /// Sends Escape.
  void sendEscape() => pty.write('\x1b');

